div.script:
document.addEventListener('DOMContentLoaded', function () {
    function extractResult(payload) {
        return (payload && payload.result) ? payload.result : (payload || {});
    }

    function notify(title, message, type) {
        var container = document.getElementById('evo_toast_container');
        if (!container || !message) {
            return;
        }
        var bgClass = (type === 'success') ? 'text-bg-success' : 'text-bg-danger';
        var toastEl = document.createElement('div');
        toastEl.className = 'toast align-items-center ' + bgClass + ' border-0';
        toastEl.setAttribute('role', 'alert');
        toastEl.setAttribute('aria-live', 'assertive');
        toastEl.setAttribute('aria-atomic', 'true');
        toastEl.innerHTML =
            '<div class="d-flex">' +
            '<div class="toast-body"><strong>' + title + ':</strong> ' + message + '</div>' +
            '<button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button>' +
            '</div>';
        container.appendChild(toastEl);
        if (window.bootstrap && window.bootstrap.Toast) {
            window.bootstrap.Toast.getOrCreateInstance(toastEl, { delay: 1800, autohide: true }).show();
        }
    }

    var flashData = document.getElementById('evo_flash_data');
    if (flashData) {
        var successMsg = (flashData.dataset.success || '').trim();
        var errorMsg = (flashData.dataset.error || '').trim();
        if (successMsg) {
            notify('Success', successMsg, 'success');
        }
        if (errorMsg) {
            notify('Error', errorMsg, 'danger');
        }
    }

    var createForm = document.querySelector('.js-evo-create-form');
    if (createForm) {
        createForm.addEventListener('submit', function (ev) {
            ev.preventDefault();
            var submitBtn = createForm.querySelector('button[type="submit"]');
            var nameInput = createForm.querySelector('input[name="name"]');
            var phoneInput = createForm.querySelector('input[name="pairing_phone"]');
            var name = (nameInput && nameInput.value ? nameInput.value : '').trim();
            var pairingPhone = (phoneInput && phoneInput.value ? phoneInput.value : '').trim();
            if (!name || !pairingPhone) {
                notify('Error', 'Please fill all required fields.', 'danger');
                return;
            }
            if (submitBtn) {
                submitBtn.disabled = true;
            }
            fetch('/evolution/instances/create_ajax', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: { name: name, pairing_phone: pairingPhone },
                    id: Date.now()
                })
            }).then(function (r) { return r.json(); }).then(function (payload) {
                var result = extractResult(payload);
                if (!result.ok) {
                    notify('Error', result.error || 'Failed to create instance.', 'danger');
                    return;
                }
                notify('Success', result.message || 'Instance created successfully.', 'success');
                if (nameInput) { nameInput.value = ''; }
                if (phoneInput) { phoneInput.value = ''; }
            }).catch(function () {
                notify('Error', 'Failed to create instance.', 'danger');
            }).finally(function () {
                if (submitBtn) {
                    submitBtn.disabled = false;
                }
            });
        });
    }

    var testForms = document.querySelectorAll('.js-evo-test-form');
    testForms.forEach(function (form) {
        form.addEventListener('submit', function (ev) {
            ev.preventDefault();
            var recordId = form.getAttribute('data-record-id');
            var submitBtn = form.querySelector('button[type="submit"]');
            if (!recordId) {
                notify('Error', 'Instance not found.', 'danger');
                return;
            }
            if (submitBtn) {
                submitBtn.disabled = true;
            }
            fetch('/evolution/instances/test_ajax', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: { record_id: parseInt(recordId, 10) },
                    id: parseInt(recordId, 10)
                })
            }).then(function (r) { return r.json(); }).then(function (payload) {
                var result = extractResult(payload);
                if (!result.ok) {
                    notify('Error', result.error || 'Failed to send test message.', 'danger');
                    return;
                }
                notify('Success', result.message || 'Test message sent successfully.', 'success');
            }).catch(function () {
                notify('Error', 'Failed to send test message.', 'danger');
            }).finally(function () {
                if (submitBtn) {
                    submitBtn.disabled = false;
                }
            });
        });
    });

    var statusButtons = document.querySelectorAll('.js-evo-check-status');
    statusButtons.forEach(function (btn) {
        btn.addEventListener('click', function () {
            var recordId = btn.getAttribute('data-record-id');
            if (!recordId) {
                notify('Error', 'Instance not found.', 'danger');
                return;
            }
            btn.disabled = true;
            var originalText = btn.textContent;
            btn.textContent = 'Checking...';
            fetch('/evolution/instances/status_check_ajax', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: { record_id: parseInt(recordId, 10) },
                    id: parseInt(recordId, 10)
                })
            }).then(function (r) { return r.json(); }).then(function (payload) {
                var result = extractResult(payload);
                if (!result.ok) {
                    notify('Error', result.error || 'Failed to refresh status.', 'danger');
                    return;
                }
                var statusEl = document.getElementById('status' + recordId);
                var syncEl = document.getElementById('sync' + recordId);
                if (statusEl) {
                    statusEl.textContent = result.status || '-';
                }
                if (syncEl) {
                    syncEl.textContent = result.last_status_sync_at || '-';
                }
                notify('Success', result.message || 'Instance status refreshed successfully.', 'success');
            }).catch(function () {
                notify('Error', 'Failed to refresh status.', 'danger');
            }).finally(function () {
                btn.disabled = false;
                btn.textContent = originalText;
            });
        });
    });

    var buttons = document.querySelectorAll('.js-evo-get-qr');
    buttons.forEach(function (btn) {
        btn.addEventListener('click', function () {
            if (btn.dataset.loading === '1') {
                return;
            }
            btn.dataset.loading = '1';
            btn.disabled = true;
            var originalText = btn.textContent;
            btn.textContent = 'Loading...';
            var recordId = btn.getAttribute('data-record-id');
            var modalId = btn.getAttribute('data-modal-id');
            fetch('/evolution/instances/qr/fetch', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: { record_id: parseInt(recordId, 10) },
                    id: parseInt(recordId, 10)
                })
            }).then(function (r) { return r.json(); }).then(function (payload) {
                var result = payload.result || {};
                if (!result.ok) {
                    notify('Error', (result.error || 'Failed to fetch QR code.'), 'danger');
                    return;
                }
                var qrImage = result.qr_code_image || '';
                var qrText = result.qr_code_text || '';
                if (qrImage.slice(0, 2) === "b'" && qrImage.slice(-1) === "'") {
                    qrImage = qrImage.slice(2, -1);
                }
                var img = document.getElementById('qrImg' + recordId);
                if (img) {
                    if (qrImage) {
                        img.src = 'data:image/png;base64,' + qrImage;
                    } else if (qrText) {
                        img.src = '/report/barcode/?type=QR&width=420&height=420&value=' + encodeURIComponent(qrText);
                    } else {
                        img.removeAttribute('src');
                    }
                }
                var modalEl = document.getElementById(modalId);
                var previewSrc = '';
                if (img && img.src) {
                    previewSrc = img.src;
                }
                if (modalEl) {
                    if (window.bootstrap && window.bootstrap.Modal) {
                        window.bootstrap.Modal.getOrCreateInstance(modalEl).show();
                    } else if (window.jQuery && window.jQuery.fn && window.jQuery.fn.modal) {
                        window.jQuery(modalEl).modal('show');
                    } else {
                        modalEl.style.display = 'block';
                        modalEl.classList.add('show');
                        modalEl.removeAttribute('aria-hidden');
                        modalEl.setAttribute('aria-modal', 'true');
                    }
                } else if (previewSrc) {
                    window.open(previewSrc, '_blank');
                }
            }).catch(function () {
                notify('Error', 'Failed to fetch QR code.', 'danger');
            }).finally(function () {
                btn.dataset.loading = '0';
                btn.disabled = false;
                btn.textContent = originalText;
            });
        });
    });
});
